def restore1270(path, actual):
    patch=(ROOT/'tools/connected_alpha/signature1271_presentation.patch').read_bytes()
    prefix=('diff --git a/'+str(path)+' b/'+str(path)+'\n').encode()
    match=[b'diff --git '+p for p in patch.split(b'diff --git ')[1:] if (b'diff --git '+p).startswith(prefix)]
    if not match:return actual
    if len(match)!=1:raise ValueError('Ambiguous1271 patch')
    with tempfile.TemporaryDirectory() as d:
        target=Path(d)/path;target.parent.mkdir(parents=True);target.write_bytes(actual)
        result=subprocess.run(['git','apply','--reverse','-'],cwd=d,input=match[0],capture_output=True)
        if result.returncode:raise ValueError('1271 differs from recorded presentation: '+str(path))
        return target.read_bytes()
def read1270(path):
    return restore1270(path,(ROOT/path).read_bytes()).decode()
